async def seed_words():
    """Seed the database with all words if not already present."""
    async with engine.begin() as conn:
        await conn.run_sync(Base.metadata.create_all)

    async with async_session_factory() as db:
        # Check existing count
        existing = await db.execute(select(Word.text_hi))
        existing_texts = set(existing.scalars().all())

        added_count = 0
        for item in WORDS_DATA:
            if item["text_hi"] not in existing_texts:
                word = Word(
                    id=str(uuid.uuid4()),
                    text_hi=item["text_hi"],
                    transliteration=item["transliteration"],
                    meaning_en=item["meaning_en"],
                    category=item["category"],
                    difficulty=item["difficulty"],
                    audio_url=item.get("audio_url"),
                )
                db.add(word)
                existing_texts.add(item["text_hi"])
                added_count += 1

        await db.commit()
        print(f"[+] Seeding complete! Added {added_count} words (Total in DB: {len(existing_texts)})")


if __name__ == "__main__":
    asyncio.run(seed_words())
